const foodSugarTypes=new Set(['glucose','fructose','maltose','lactose','sucrose']);
const foodSampleTypes=new Set([...foodSugarTypes,'foodStarch','starch','protein','lipid']);
const foodReagentTypes=new Set(['benedict','biuret','cabbage','foodPHBuffer']);
const foodTimers=new Map();
let foodProtocol='reducing';
function registerFoodReagents(){const group='Food tests & natural indicators',rows=[
 ['Glucose solution','C₆H₁₂O₆ · 0.05 M','glucose',group,'#f7faf8','colourless'],['Fructose solution','C₆H₁₂O₆ · 0.05 M','fructose',group,'#f7faf8','colourless'],['Maltose solution','C₁₂H₂₂O₁₁ · 0.025 M','maltose',group,'#f7faf8','colourless'],['Lactose solution','C₁₂H₂₂O₁₁ · 0.025 M','lactose',group,'#f7faf8','colourless'],['Sucrose solution','C₁₂H₂₂O₁₁ · 0.05 M','sucrose',group,'#f7faf8','colourless'],['Starch food sample','Starch · 2 g/L reference suspension','foodStarch',group,'#f4f1e8','slightly cloudy'],['Albumin protein solution','Albumin · 10 g/L reference solution','protein',group,'#f4f1e8','pale / slightly opalescent'],['Vegetable oil','Triglyceride mixture · model lipid','lipid',group,'#e4cd7a','pale yellow oil'],["Benedict’s reagent",'Alkaline Cu(II)–citrate mixture · standard formulation','benedict',group,'#4b9acb','blue'],['Biuret reagent','Alkaline Cu(II) reagent · premixed formulation','biuret',group,'#6eadd0','blue'],['Red cabbage indicator','Anthocyanin extract · qualitative indicator','cabbage',group,'#8654b5','purple']];for(const pH of [2,4,7,9,11,13])rows.push(['pH '+pH+' reference buffer','Reference buffer · pH '+pH,'foodPHBuffer',group,'#f7faf8','colourless']);for(const r of rows)if(!reagents.some(x=>x[0]===r[0]&&x[2]===r[2]))reagents.push(r);}
function foodResult(product,equation,note,color,extra={}){return {product,equation,note,color,solutionColor:color,gas:null,precipitate:false,status:'qualitative',foodTest:true,...extra};}
function foodUnknown(note){return foodResult('Food-test prediction unavailable','No unique equation assigned.',note,'#f7faf8',{status:'unsupported'});}
function foodAcidBalance(entries){let acid=0,base=0;for(const e of entries){if(e.type==='acid')acid+=(e.n||0)*(e.f==='H2SO4'?2:1);if(e.type==='base')base+=(e.n||0)*(e.f==='Ca(OH)2'?2:1);if(e.type==='bicarbonate')base+=e.n||0;}return {acid,base,residual:acid-base};}
function foodCabbageShade(pH){const anchors=[[1,'#d52f4d'],[3,'#df538e'],[5,'#af549d'],[7,'#8156b3'],[8,'#507db7'],[9,'#398d9a'],[10,'#4ba272'],[11,'#a6b34e'],[12,'#d4c755'],[14,'#c8a94c']];if(pH<=1)return anchors[0][1];for(let i=1;i<anchors.length;i++)if(pH<=anchors[i][0]){const t=(pH-anchors[i-1][0])/(anchors[i][0]-anchors[i-1][0]);return benchTint([[anchors[i-1][1],1-t],[anchors[i][1],t]]);}return anchors.at(-1)[1];}
function foodCabbagePH(entries){const buffers=entries.filter(e=>e.type==='foodPHBuffer'),active=entries.filter(e=>!['cabbage','water'].includes(e.type));if(buffers.length){if(active.some(e=>e.type!=='foodPHBuffer')||new Set(buffers.map(e=>e.formula)).size>1)return null;return Number((String(buffers[0].formula).match(/pH\s*(\d+)/i)||[])[1]);}if(!active.length)return 7;if(active.some(e=>!['acid','base','ammonia','ammonium','carbonate','bicarbonate'].includes(e.type)||e.n==null||e.c>1||e.c<0))return null;
 const V=entries.reduce((s,e)=>s+e.volume/1000,0);let fixed=0,cl=0,sulfate=0,acetate=0,N=0,carbon=0;for(const e of active){const n=e.n;if(e.f==='HCl')cl+=n;else if(e.f==='H2SO4')sulfate+=n;else if(e.f==='CH3COOH')acetate+=n;else if(e.f==='NaOH')fixed+=n;else if(e.f==='Ca(OH)2')fixed+=2*n;else if(e.f==='NH3')N+=n;else if(e.f==='NH4Cl'){N+=n;cl+=n;}else if(e.f==='Na2CO3'){fixed+=2*n;carbon+=n;}else if(e.f==='NaHCO3'){fixed+=n;carbon+=n;}else return null;}
 let lo=-16,hi=1;for(let i=0;i<100;i++){const mid=(lo+hi)/2,H=10**mid,k1=4.45e-7,k2=4.69e-11,den=H*H+k1*H+k1*k2,pos=H+fixed/V+N/V*H/(H+5.6e-10),neg=1e-14/H+cl/V+sulfate/V*(1+.012/(H+.012))+acetate/V*1.75e-5/(H+1.75e-5)+carbon/V*(k1*H+2*k1*k2)/den;if(pos>neg)hi=mid;else lo=mid;}return -(lo+hi)/2;
}
function foodPredict(items,conditions={}){const e=benchEntries(items),has=t=>e.some(x=>x.type===t),food=e.some(x=>foodReagentTypes.has(x.type)||foodSampleTypes.has(x.type)&&x.type!=='starch');if(!food)return null;const allowed=new Set([...foodSampleTypes,...foodReagentTypes,'water','iodine','ethanol','acid','base','bicarbonate']);if(e.some(x=>!allowed.has(x.type))&&!has('cabbage'))return foodUnknown('Other chemicals interfere with the reference food tests. Use a fresh aliquot and the named test reagents.');const assays=['benedict','biuret','iodine','cabbage'].filter(has);if(assays.length>1)return foodUnknown('Use a separate clean aliquot for each food test; mixing test reagents makes the result uninterpretable.');if(e.some(x=>foodSugarTypes.has(x.type)&&(x.n==null||!Number.isFinite(x.n)||x.n<0)))return foodUnknown('Enter a finite, non-negative sugar concentration.');
 if(has('cabbage')){const ph=foodCabbagePH(e);if(ph==null)return foodUnknown('The pH / buffer capacity of this composition is not modeled. Use one reference buffer, or simple measured acid/base solutions with the cabbage extract.');if((conditions.temperature||25)>60)return foodUnknown('Cool the sample before reading the anthocyanin indicator; heat-dependent pigment degradation is not modeled.');const label=ph<3?'red / pink':ph<6?'pink-purple':ph<8?'purple / violet':ph<9?'blue':ph<11?'blue-green / green':'yellow-green / yellow';return foodResult('Red cabbage anthocyanin indicator','Anthocyanin acid forms ⇌ hydrated / base forms',`Approximate ${label} colour at ${has('foodPHBuffer')?'reference':'modeled'} pH ${ph.toFixed(2)}. Anthocyanin forms change with acidity. This is a qualitative colour guide; extraction, concentration and time affect the shade. Strong-alkali fading is not simulated.` ,foodCabbageShade(ph),{pH:ph,foodTest:'anthocyanin',foodInference:'The colour indicates an approximate acidity range, not an exact measured pH. Reference-buffer pH is assumed unchanged by a small indicator addition.'});}
 const balance=foodAcidBalance(e),sugars=e.filter(x=>foodSugarTypes.has(x.type)&&x.n>0),hydrolyzed=sugars.some(x=>x.type==='sucrose'&&x.foodHydrolyzed),V=e.reduce((s,x)=>s+x.volume/1000,0)||1;
 if(has('benedict')){if(e.some(x=>['biuret','cabbage','ethanol','lipid'].includes(x.type)))return foodUnknown('This mixture is unsuitable for a clean Benedict’s test.');const reagent=e.filter(x=>x.type==='benedict');if(reagent.some(x=>x.foodAssayContaminated))return foodUnknown('This previously developed Benedict’s aliquot was altered. Use a fresh aliquot rather than interpreting a reused reagent mixture.');if(balance.residual>1e-9||hydrolyzed&&reagent.some(x=>!x.foodNeutralizedBeforeBenedict))return foodResult('Benedict’s test not interpretable','Acid neutralisation is required before the alkaline Cu(II) test.','Use a fresh hydrolyzed aliquot: cool, neutralise the acid, then add Benedict’s reagent and heat. A blue acidic mixture is not a valid negative test.','#4b9acb',{status:'conditional',foodTest:'benedict'});if(!reagent.every(x=>x.foodBenedictReady))return foodResult('Benedict’s test awaiting heating','R–CHO + 2Cu²⁺ + 5OH⁻ → R–COO⁻ + Cu₂O(s) + 3H₂O','The mixture is initially blue. Mix, then use the Food & pH tests water-bath control (or heat and hold with the bench apparatus). No negative conclusion can be drawn before adequate heating.','#4b9acb',{status:'conditional',foodTest:'benedict'});
 let reducing=sugars.reduce((s,x)=>s+x.n*(x.type==='sucrose'?(x.foodHydrolyzed?2:0):1),0);const cu=reagent.reduce((s,x)=>s+x.volume/1000*.07,0),fraction=cu>0?Math.min(1,2*reducing/cu):0;if(reducing<=1e-12)return foodResult('Negative Benedict’s test','No reduction of the Benedict Cu(II) reagent is predicted.','After the required heating, the reagent remains blue: no reducing sugar is detected in these reference materials. An untreated sucrose solution can give this result. A negative test alone does not establish the presence of a non-reducing sugar.','#4b9acb',{foodTest:'benedict',foodInference:'Compare a fresh acid-hydrolyzed, cooled and neutralised aliquot with the untreated aliquot. Negative before and positive after hydrolysis is consistent with a hydrolysable non-reducing sugar.'});const colour=fraction<.2?'#789c63':fraction<.45?'#c5bd48':fraction<.75?'#df913a':'#bf512c',label=fraction<.2?'green':fraction<.45?'yellow':fraction<.75?'orange':'brick-red';return foodResult('Positive Benedict’s test · copper(I) oxide','R–CHO + 2Cu²⁺ + 5OH⁻ → R–COO⁻ + Cu₂O(s) + 3H₂O',`Heating gives a ${label} suspension with Cu₂O precipitate. Reducing sugars reduce blue Cu(II) to copper(I). Fructose also tests positive through alkaline isomerisation. The colour scale is a teaching approximation based on reducing equivalents and reagent ratio; it is not a quantitative calibration.`,colour,{precipitate:true,precipitateColor:'#bf512c',solutionColor:benchTint([['#4b9acb',1-fraction],['#f7faf8',fraction]]),foodTest:'benedict',foodInference:hydrolyzed?'Hydrolysis produced reducing glucose and fructose. Compare this positive result with a negative untreated aliquot to infer a hydrolysable non-reducing sugar.':'A positive result supports reducing activity; it is not specific to glucose and other reducing substances can interfere.'});}
 if(has('biuret')){if(has('acid')||has('base')||has('ethanol')||has('lipid'))return foodUnknown('Use the premixed Biuret reagent with a fresh aqueous sample, without extra acid, alkali or solvent.');const positive=has('protein');return foodResult(positive?'Positive Biuret test · protein':'Negative Biuret test','Cu(II) + peptide groups ⇌ violet coordination complex (alkaline medium)',positive?'The blue reagent becomes violet / purple as Cu(II) coordinates peptide groups. No heating is required; the model shows the developed colour.':'The reagent stays blue: no protein is detected in the reference sample. No heating is required.',positive?'#9056ad':'#6eadd0',{foodTest:'biuret',foodInference:positive?'The violet complex is consistent with multiple peptide bonds, as in protein; it is not a protein-specific identity test.':'A negative result is limited to the reference sample and qualitative model sensitivity.'});}
 if(has('iodine')){if(has('acid')||has('base')||has('ethanol')||has('lipid'))return foodUnknown('Use iodine on a fresh aqueous sample at room temperature.');if((conditions.temperature||25)>60)return foodResult('Iodine–starch test · cool before reading','Polyiodide + starch ⇌ coloured inclusion complex','Heating can weaken the blue-black starch–iodine colour. Cool before interpreting the test.','#b98a46',{status:'conditional',foodTest:'starch'});const positive=has('foodStarch')||has('starch');return foodResult(positive?'Positive iodine test · starch':'Negative iodine test','Polyiodide + starch ⇌ blue-black inclusion complex',positive?'Iodine changes from yellow-brown to blue-black in the presence of starch. This is a complex / inclusion colour, not a precipitate.':'Iodine remains yellow-brown; the reference sample gives no starch colour.',positive?'#25375d':'#b17b35',{foodTest:'starch',foodInference:positive?'The blue-black inclusion complex is consistent with starch (especially amylose).':'No starch is detected by this qualitative reference test.'});}
 if(has('ethanol')||has('lipid')){if(e.some(x=>!['ethanol','lipid','water'].includes(x.type)))return foodUnknown('For the emulsion test use only the lipid reference, ethanol and water on a fresh sample.');if(has('ethanol')&&has('water')){const extracted=e.some(x=>x.type==='lipid'&&x.foodEthanolExtracted);return foodResult(extracted?'Positive ethanol-emulsion test':'Emulsion test · no prepared lipid extract','Lipid dissolved in ethanol + water → dispersed lipid droplets (physical emulsion)',extracted?'Adding the ethanol lipid extract to water produces a white / milky emulsion of tiny lipid droplets. This is a physical dispersion, not a solid precipitate.':has('lipid')?'Prepare the ethanol extract before adding water. An unmixed oil layer is not the positive emulsion-test endpoint.':'The ethanol–water control remains clear; no lipid emulsion forms.',extracted?'#f0f0e9':'#f7faf8',{foodTest:'emulsion',emulsion:extracted,status:has('lipid')&&!extracted?'conditional':'qualitative',foodInference:extracted?'The white emulsion supports the presence of an ethanol-extractable lipid in this reference system.':'Use the prescribed extraction and dilution sequence before drawing an inference.'});}return foodResult('Lipid / ethanol preparation','Physical extraction; no new covalent product.','Mix oil with ethanol, then click Prepare ethanol extract. Transfer the extract into a clean vessel of water to develop an emulsion.','#e5d9a5',{foodTest:'emulsion',status:'conditional'});}
 if(sugars.some(x=>x.type==='sucrose')&&has('acid')){if(hydrolyzed)return foodResult('Hydrolyzed sucrose · glucose and fructose','C₁₂H₂₂O₁₁ + H₂O → C₆H₁₂O₆ (glucose) + C₆H₁₂O₆ (fructose)',balance.residual>1e-9?'Acid hydrolysis is complete in the teaching model. Cool, then neutralise with sodium hydrogencarbonate before adding Benedict’s reagent.':'Acid has been neutralised. After cooling, add Benedict’s reagent and heat to test the reducing products.','#f7faf8',{foodTest:'hydrolysis',gas:has('bicarbonate')&&balance.acid>0?'carbonDioxide':null,foodInference:'A positive test after hydrolysis must be compared with the untreated sample; acid treatment can generate reducing sugars.'});return foodResult('Sucrose hydrolysis · heating required','C₁₂H₂₂O₁₁ + H₂O → glucose + fructose (H⁺, heat)','Heat a fresh sucrose aliquot with dilute hydrochloric acid in the simulated water bath. Then cool and neutralise before testing. Do not add Benedict’s reagent during hydrolysis.','#f7faf8',{status:'conditional',foodTest:'hydrolysis'});}
 if(has('acid')||has('base')||has('bicarbonate'))return foodUnknown('This food mixture has no validated test pathway. Use the named food-test protocol on a fresh aliquot.');return foodResult('Prepared food reference sample','No test reaction yet.','Add one food-test reagent to a fresh aliquot, mix, and follow its preparation / heating procedure.','#f7faf8',{foodTest:'sample',status:'conditional'});
}
function foodAfterAddition(a){if(a.contents.slice(0,-1).some(c=>c.type==='benedict'&&c.foodBenedictReady))a.contents.filter(c=>c.type==='benedict').forEach(c=>c.foodAssayContaminated=true);a.foodHeatSeconds=0;const last=a.contents?.at(-1);if(last?.type==='benedict'){const before=benchEntries(a.contents.slice(0,-1)),b=foodAcidBalance(before);last.foodNeutralizedBeforeBenedict=b.residual<=1e-9&&(a.temperature||25)<=40;}if(a.foodBathActive){clearInterval(foodTimers.get(a.id));foodTimers.delete(a.id);a.foodBathActive=false;a.foodMessage='Mixture changed: restart the water-bath treatment.';}}
function foodHeatKind(a){const e=benchEntries(a.contents),has=t=>e.some(x=>x.type===t);if(e.some(x=>['ethanol','lipid',...['acetone','hexane','methanol','propanol','isopropanol','acetonitrile','heptane','toluene','cyclohexane','ethylAcetate','dichloromethane']].includes(x.type)))return null;if(has('benedict'))return 'benedict';if(has('sucrose')&&has('acid')&&foodAcidBalance(e).residual/Math.max(1e-12,e.reduce((s,x)=>s+x.volume/1000,0))>=.001&&!has('biuret')&&!has('iodine'))return 'hydrolysis';return null;}
function foodHeatingStep(a,seconds=30){if(!a.mixed||(a.temperature||25)<80)return;const kind=foodHeatKind(a);if(!kind)return;a.foodHeatSeconds=(a.foodHeatSeconds||0)+seconds;if(a.foodHeatSeconds>=180){for(const c of a.contents){if(kind==='hydrolysis'&&c.type==='sucrose')c.foodHydrolyzed=true;if(kind==='benedict'&&c.type==='benedict')c.foodBenedictReady=true;}a.foodMessage=kind==='hydrolysis'?'Hydrolysis treatment complete. Cool, neutralise the acid, then add Benedict’s reagent.':'Benedict’s heating complete. Read Reaction results.';}}
function foodNeedsHeatHold(a){return (a.temperature||25)>=80&&!!foodHeatKind(a)&&(a.foodHeatSeconds||0)<180;}
function foodAction(action){const a=selectedEquipment();const message=document.getElementById('foodStatus');const fail=text=>{if(message)message.textContent=text;};if(!a||!acceptsLiquid(a.type))return fail('Select a liquid-containing vessel on the bench.');if(action==='cool'){if(a.foodBathActive)return fail('Wait for the water-bath treatment to finish.');a.temperature=25;a.heatObservation='Sample cooled to room temperature.';a.foodMessage='Cooled to 25 °C. Neutralise residual acid before adding Benedict’s reagent.';redrawBench();persistWorkspace();return;}if(action==='extract'){const e=benchEntries(a.contents);if(!e.some(x=>x.type==='ethanol')||!e.some(x=>x.type==='lipid')||e.some(x=>!['ethanol','lipid'].includes(x.type)))return fail('Use a fresh oil + ethanol mixture, without water or other test reagents.');a.contents.filter(c=>c.type==='lipid').forEach(c=>c.foodEthanolExtracted=true);a.mixed=true;a.foodMessage='Ethanol extract prepared. Transfer into water in a clean vessel.';redrawBench();persistWorkspace();return;}if(action==='bath'){if(a.foodBathActive)return;if(a.heating)return fail('Stop the existing heater before using this water-bath control.');a.mixed=true;if(!foodHeatKind(a))return fail('Use Benedict’s mixture, or fresh sucrose plus dilute acid. Organic solvents are excluded from this water-bath treatment.');a.foodBathActive=true;a.foodHeatSeconds=0;a.foodMessage='Water bath warming (accelerated)…';const id=a.id,timer=setInterval(()=>{const vessel=apparatus.find(v=>v.id===id);if(!vessel){clearInterval(timer);foodTimers.delete(id);return;}vessel.temperature=Math.min(90,(vessel.temperature||25)+15);foodHeatingStep(vessel,30);if((vessel.foodHeatSeconds||0)<180)vessel.foodMessage=`Water bath ${vessel.temperature} °C · hot hold ${vessel.foodHeatSeconds||0} / 180 simulated seconds.`;else{clearInterval(timer);foodTimers.delete(id);vessel.foodBathActive=false;}if(page==='bench')redrawBench();persistWorkspace();},400);foodTimers.set(id,timer);redrawBench();}}
const foodGuides={reducing:['Reducing sugars','Use a clean tube. Add 2 mL glucose, fructose, maltose or lactose solution and 2 mL Benedict’s reagent. Mix, then heat in the simulated water bath. Use water as a negative control. Blue before heating is inconclusive; a green-to-brick-red Cu₂O suspension after heating is positive.'],nonreducing:['Non-reducing sugar (sucrose)','First test an untreated sucrose aliquot with Benedict’s and heat: it should remain blue. In a fresh tube add 2 mL sucrose and 1 mL 0.1 mol/L HCl. Mix and water-bath heat, then cool. Add 1 mL 0.1 mol/L sodium hydrogencarbonate to neutralise (CO₂ evolves), then 2 mL Benedict’s and heat again. Compare the negative untreated and positive hydrolyzed aliquots.'],starch:['Starch / iodine','Use a fresh starch aliquot with a small amount of Iodine solution. Mix and read at room temperature. Blue-black is positive; yellow-brown is negative. The colour is a complex, not a precipitate.'],protein:['Protein / Biuret','Use a fresh albumin aliquot with premixed Biuret reagent. Mix at room temperature. Violet / purple is positive; the blue reagent is negative. Heating is not needed.'],lipid:['Lipid / ethanol emulsion','Use a fresh tube with 0.2 mL vegetable oil and 2 mL ethanol. Mix and select Prepare ethanol extract. Transfer into a clean vessel containing 5 mL distilled water. A white emulsion is positive; ethanol + water alone stays clear. Do not heat ethanol.'],cabbage:['Red cabbage / anthocyanins','Add a small amount of Red cabbage indicator to a reference buffer or measured simple acid/base solution. Mix at room temperature. Use the pH reference buffers to compare acidic reds/pinks, neutral violet, then alkaline blue/green/yellow. Use separate vessels for the reference colours.']};
function foodPanelHtml(){const a=selectedEquipment(),guide=foodGuides[foodProtocol];return `<div class="food-guide-top"><label for="foodProtocol">Test procedure<select id="foodProtocol">${Object.entries(foodGuides).map(([k,v])=>`<option value="${k}" ${foodProtocol===k?'selected':''}>${v[0]}</option>`).join('')}</select></label><div><b>${a?esc(benchVesselLabel(a)):'Select a vessel on the bench'}</b><small>${a?(a.temperature||25)+' °C · '+(a.volume||0).toFixed(1)+' mL':''}</small></div></div><p class="food-guide-instructions">${esc(guide[1])}</p><div class="ch-actions"><button type="button" class="btn soft small" data-food-action="bath" ${a?.foodBathActive?'disabled':''}>${a?.foodBathActive?'Water bath running…':'Heat in water bath'}</button><button type="button" class="btn secondary small" data-food-action="cool">Cool sample</button><button type="button" class="btn secondary small" data-food-action="extract">Prepare ethanol extract</button><button type="button" class="btn secondary small" id="foodViewResults">View reaction results</button></div><p id="foodStatus" role="status">${esc(a?.foodMessage||'Add the sample and reagents using the normal bench controls. These treatment buttons act on the selected vessel.')}</p><div class="food-cabbage-scale">${[2,4,7,9,11,13].map(p=>`<span style="border-top-color:${foodCabbageShade(p)}">pH ${p}</span>`).join('')}</div><p class="muted">Qualitative reference tests: use a fresh aliquot for each assay. Water-bath warming and a 3-minute hot hold at 80–90 °C are accelerated; actual reaction times and colours depend on conditions. Protein/starch references and mixed reagents are standard formulations, not single-solute molar solutions. <a href="food-tests-reference.txt" target="_blank" rel="noopener">Methods, model limits &amp; references</a></p>`;}
function foodRefreshPanel(){const el=document.getElementById('foodTestsPanel');if(!el)return;el.innerHTML=foodPanelHtml();document.getElementById('foodProtocol').onchange=e=>{foodProtocol=e.target.value;foodRefreshPanel();};el.querySelectorAll('[data-food-action]').forEach(b=>b.onclick=()=>foodAction(b.dataset.foodAction));document.getElementById('foodViewResults').onclick=()=>{benchResultsMode='vessel';const target=document.getElementById('benchPanelResults');if(target.hidden)toggleBenchTask('results');else benchRefreshResults();target.scrollIntoView({block:'start',behavior:'smooth'});};}
